export type AudioFormat = 'mp3' | 'wav' | 'flac'
export type SourceKind = 'device' | 'drive'

export interface AudioValidation {
  ok: boolean
  format?: AudioFormat
  message?: string
}

export interface LoopRegion {
  start: number
  end: number
  enabled: boolean
}

const formatByMime: Readonly<Record<string, AudioFormat>> = {
  'audio/mpeg': 'mp3',
  'audio/mp3': 'mp3',
  'audio/wav': 'wav',
  'audio/wave': 'wav',
  'audio/x-wav': 'wav',
  'audio/vnd.wave': 'wav',
  'audio/flac': 'flac',
  'audio/x-flac': 'flac',
}

export function audioFormatFromName(name: string): AudioFormat | null {
  const match = name.trim().toLowerCase().match(/\.([a-z0-9]+)$/)
  const extension = match?.[1]
  return extension === 'mp3' || extension === 'wav' || extension === 'flac'
    ? extension
    : null
}

export function validateAudioFile(file: Pick<File, 'name' | 'type'>): AudioValidation {
  const extensionFormat = audioFormatFromName(file.name)
  if (!extensionFormat) return { ok: false, message: '只支援 MP3、WAV 與 FLAC 音檔。' }

  const normalizedMime = file.type.split(';', 1)[0]?.trim().toLowerCase() ?? ''
  if (!normalizedMime || normalizedMime === 'application/octet-stream') {
    return { ok: true, format: extensionFormat }
  }

  const mimeFormat = formatByMime[normalizedMime]
  if (!mimeFormat) return { ok: false, message: '選取的檔案不是支援的音訊格式。' }
  if (mimeFormat !== extensionFormat) {
    return { ok: false, message: '檔案副檔名與音訊格式不一致。' }
  }
  return { ok: true, format: extensionFormat }
}

export function formatBytes(bytes: number): string {
  if (!Number.isFinite(bytes) || bytes <= 0) return '0 B'
  const units = ['B', 'KB', 'MB', 'GB'] as const
  const index = Math.min(Math.floor(Math.log(bytes) / Math.log(1024)), units.length - 1)
  const value = bytes / 1024 ** index
  return index === 0 ? `${Math.floor(value)} B` : `${value.toFixed(1)} ${units[index]}`
}

export function formatTime(value: number, milliseconds = false): string {
  if (!Number.isFinite(value) || value < 0) return milliseconds ? '00:00.000' : '00:00'
  const scale = milliseconds ? 1_000 : 1
  const total = Math.round(value * scale)
  const secondsTotal = Math.floor(total / scale)
  const hours = Math.floor(secondsTotal / 3_600)
  const minutes = Math.floor((secondsTotal % 3_600) / 60)
  const seconds = secondsTotal % 60
  const base = hours > 0
    ? `${hours}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`
    : `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`
  if (!milliseconds) return base
  return `${base}.${(total % 1_000).toString().padStart(3, '0')}`
}

export function playableStart(currentTime: number, duration: number, loop: LoopRegion | null): number {
  if (duration <= 0) return 0
  if (loop?.enabled && (currentTime < loop.start || currentTime >= loop.end)) return loop.start
  if (currentTime >= duration - 0.05) return loop?.enabled ? loop.start : 0
  return Math.min(Math.max(currentTime, 0), duration)
}
