import { useEffect, useRef, useState } from 'react'
import { activateAudioContext } from '../lib/audio-unlock'
import { formatTime } from '../lib/audio'
import { stemIds, type StemId } from '../lib/separation'
import { createStemMixerSettings, stemGain, type StemMixerSettings } from '../lib/stem-mixer'

const labels: Record<StemId, string> = { bass: 'Bass', drums: 'Drums', vocals: 'Vocals', other: 'Other' }

interface StreamingGraph {
  context: AudioContext
  elements: Record<StemId, HTMLAudioElement>
  urls: string[]
  sources: Record<StemId, MediaElementAudioSourceNode>
  gains: Record<StemId, GainNode>
  master: GainNode
}

interface Props {
  stems: Record<StemId, Blob>
  duration: number
  onBeforePlay(): void
  registerPause(pause: (() => void) | null): void
  onError(message: string): void
  settingsHolder: { current: StemMixerSettings }
}

/** Stream four long M4As through native media decoders. Unlike decodeAudioData,
 * this does not expand an entire six-minute song to four huge AudioBuffers. */
export function MergedStemMixer({ stems, duration, onBeforePlay, registerPause, onError, settingsHolder }: Props) {
  const [settings, setSettings] = useState(() => settingsHolder.current ?? createStemMixerSettings())
  settingsHolder.current = settings
  const [position, setPosition] = useState(0)
  const [playing, setPlaying] = useState(false)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const graphRef = useRef<StreamingGraph | null>(null)
  const timerRef = useRef<number | null>(null)
  const playingRef = useRef(false)
  const pauseRef = useRef<() => void>(() => undefined)
  const bassBlob = stems.bass
  const drumsBlob = stems.drums
  const vocalsBlob = stems.vocals
  const otherBlob = stems.other

  const pause = () => {
    const graph = graphRef.current
    if (!graph) return
    for (const id of stemIds) graph.elements[id].pause()
    if (timerRef.current !== null) window.clearInterval(timerRef.current)
    timerRef.current = null
    playingRef.current = false
    setPlaying(false)
    setPosition(Math.min(duration, graph.elements.bass.currentTime || 0))
  }
  pauseRef.current = pause

  useEffect(() => {
    registerPause(() => pauseRef.current())
    return () => registerPause(null)
  }, [registerPause])

  useEffect(() => {
    let active = true
    let graph: StreamingGraph | null = null
    const prepare = () => {
      const context = new AudioContext()
      const urls: string[] = []
      try {
        const master = context.createGain()
        master.gain.value = 0.8
        master.connect(context.destination)
        const elements = {} as Record<StemId, HTMLAudioElement>
        const sources = {} as Record<StemId, MediaElementAudioSourceNode>
        const gains = {} as Record<StemId, GainNode>
        const blobs: Record<StemId, Blob> = { bass: bassBlob, drums: drumsBlob, vocals: vocalsBlob, other: otherBlob }
        for (const id of stemIds) {
          const element = new Audio()
          element.preload = 'metadata'
          element.setAttribute('playsinline', '')
          element.src = URL.createObjectURL(blobs[id])
          urls.push(element.src)
          const source = context.createMediaElementSource(element)
          const gain = context.createGain()
          gain.gain.value = stemGain(id, settingsHolder.current)
          source.connect(gain).connect(master)
          elements[id] = element
          sources[id] = source
          gains[id] = gain
        }
        graph = { context, elements, urls, sources, gains, master }
        if (!active) return
        graphRef.current = graph
        setLoading(false)
      } catch (reason) {
        for (const url of urls) URL.revokeObjectURL(url)
        void context.close()
        if (active) {
          const message = reason instanceof Error ? reason.message : '無法準備整首四軌播放器。'
          setError(message)
          onError(message)
          setLoading(false)
        }
      }
    }
    prepare()
    return () => {
      active = false
      if (timerRef.current !== null) window.clearInterval(timerRef.current)
      if (!graph) return
      for (const id of stemIds) {
        graph.elements[id].pause()
        graph.elements[id].removeAttribute('src')
        graph.elements[id].load()
        graph.sources[id].disconnect()
        graph.gains[id].disconnect()
      }
      graph.master.disconnect()
      for (const url of graph.urls) URL.revokeObjectURL(url)
      if (graph.context.state !== 'closed') void graph.context.close()
      graphRef.current = null
    }
  }, [bassBlob, drumsBlob, onError, otherBlob, settingsHolder, vocalsBlob])

  useEffect(() => {
    const graph = graphRef.current
    if (!graph) return
    for (const id of stemIds) graph.gains[id].gain.setTargetAtTime(stemGain(id, settings), graph.context.currentTime, 0.015)
  }, [settings, loading])

  const play = () => {
    const graph = graphRef.current
    if (!graph || playingRef.current) return
    setError(null)
    onBeforePlay()
    const startAt = graph.elements.bass.currentTime >= duration - 0.02 ? 0 : graph.elements.bass.currentTime
    for (const id of stemIds) graph.elements[id].currentTime = startAt
    // Both resume() and all four play() calls happen in the same tap.
    const activation = graph.context.state === 'running' ? Promise.resolve() : activateAudioContext(graph.context)
    const starts = stemIds.map((id) => graph.elements[id].play())
    void Promise.all([activation, ...starts]).catch((reason: unknown) => {
      pauseRef.current()
      const message = reason instanceof Error ? reason.message : 'iPhone 無法播放整首四軌。'
      setError(message)
      onError(message)
    })
    playingRef.current = true
    setPlaying(true)
    timerRef.current = window.setInterval(() => {
      const current = graph.elements.bass.currentTime
      if (current >= duration - 0.02 || graph.elements.bass.ended) {
        pauseRef.current()
        setPosition(duration)
        return
      }
      // Do not hard-seek a playing media element to correct small drift. On
      // iPhone Safari a seek can empty its decoder buffer and produce a brief
      // silent gap. The tracks are aligned on Play and on an explicit seek.
      setPosition(current)
    }, 100)
  }

  const seek = (value: number) => {
    const graph = graphRef.current
    if (!graph) return
    const next = Math.max(0, Math.min(duration, value))
    for (const id of stemIds) graph.elements[id].currentTime = next
    setPosition(next)
  }

  return (
    <section className="stem-mixer" aria-label="整首四軌播放器">
      <div className="stem-transport">
        <button type="button" disabled={loading || !graphRef.current} onClick={() => playing ? pause() : play()}>
          {loading ? '載入四軌…' : playing ? '暫停' : '播放整首四軌'}
        </button>
        <span>{formatTime(position, true)} / {formatTime(duration, true)}</span>
      </div>
      <input className="stem-seek" type="range" min="0" max={duration} step="0.01" value={position} aria-label="整首四軌播放位置" onChange={(event) => seek(Number(event.target.value))} />
      <div className="stem-tracks">
        {stemIds.map((id) => (
          <div className="stem-track" key={id}>
            <div className="stem-track-main">
              <strong>{labels[id]}</strong>
              <div className="stem-track-actions">
                <button type="button" className={settings.muted[id] ? 'active' : ''} aria-pressed={settings.muted[id]} onClick={() => setSettings((previous) => ({ ...previous, muted: { ...previous.muted, [id]: !previous.muted[id] } }))}>{settings.muted[id] ? '已靜音' : '靜音'}</button>
                <button type="button" className={settings.solo[id] ? 'active' : ''} aria-pressed={settings.solo[id]} onClick={() => setSettings((previous) => ({ ...previous, solo: { ...previous.solo, [id]: !previous.solo[id] } }))}>Solo</button>
              </div>
            </div>
            <label>
              <span>音量 {Math.round(settings.volume[id] * 100)}%</span>
              <input type="range" min="0" max="1" step="0.01" value={settings.volume[id]} aria-label={`${labels[id]} 音量`} onChange={(event) => setSettings((previous) => ({ ...previous, volume: { ...previous.volume, [id]: Number(event.target.value) } }))} />
            </label>
          </div>
        ))}
      </div>
      {error && <p className="stem-mixer-error" role="alert">{error}</p>}
      <small>每軌是一個持續增長的 M4A；播放時串流解碼，不會一次解開整首歌曲。</small>
    </section>
  )
}
