import type { AudioFormat, SourceKind } from './audio'

export interface StoredAudio {
  key: 'current'
  name: string
  type: string
  size: number
  format: AudioFormat
  sourceKind: SourceKind
  importedAt: string
  blob: Blob
}

const databaseName = 'transcribe-mobile-practice'
const storeName = 'audio-library'
const databaseVersion = 2

function openDatabase(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(databaseName, databaseVersion)
    request.onupgradeneeded = (event) => {
      const database = request.result
      if (!database.objectStoreNames.contains(storeName)) {
        database.createObjectStore(storeName, { keyPath: 'key' })
      } else if (event.oldVersion < 2 && request.transaction) {
        const store = request.transaction.objectStore(storeName)
        const cursorRequest = store.openCursor()
        cursorRequest.onsuccess = () => {
          const cursor = cursorRequest.result
          if (!cursor) return
          const value = cursor.value as StoredAudio & { waveform?: unknown }
          if ('waveform' in value) {
            delete value.waveform
            cursor.update(value)
          }
          cursor.continue()
        }
      }
    }
    request.onsuccess = () => resolve(request.result)
    request.onerror = () => reject(request.error ?? new Error('無法開啟本機音訊資料庫。'))
  })
}

function complete(transaction: IDBTransaction): Promise<void> {
  return new Promise((resolve, reject) => {
    transaction.oncomplete = () => resolve()
    transaction.onerror = () => reject(transaction.error ?? new Error('本機儲存失敗。'))
    transaction.onabort = () => reject(transaction.error ?? new Error('本機儲存已取消。'))
  })
}

export async function saveAudio(audio: Omit<StoredAudio, 'key'>): Promise<StoredAudio> {
  const stored: StoredAudio = { ...audio, key: 'current' }
  const database = await openDatabase()
  try {
    const transaction = database.transaction(storeName, 'readwrite')
    transaction.objectStore(storeName).put(stored)
    await complete(transaction)
    return stored
  } finally {
    database.close()
  }
}

export async function loadAudio(): Promise<StoredAudio | null> {
  const database = await openDatabase()
  try {
    return await new Promise((resolve, reject) => {
      const request = database.transaction(storeName, 'readonly').objectStore(storeName).get('current')
      request.onsuccess = () => resolve((request.result as StoredAudio | undefined) ?? null)
      request.onerror = () => reject(request.error ?? new Error('無法讀取本機音檔。'))
    })
  } finally {
    database.close()
  }
}

export async function deleteAudio(): Promise<void> {
  const database = await openDatabase()
  try {
    const transaction = database.transaction(storeName, 'readwrite')
    transaction.objectStore(storeName).delete('current')
    await complete(transaction)
  } finally {
    database.close()
  }
}

export async function requestPersistentStorage(): Promise<boolean | null> {
  if (!navigator.storage?.persist) return null
  try {
    return await navigator.storage.persist()
  } catch {
    return false
  }
}

export async function getStorageEstimate(): Promise<StorageEstimate | null> {
  if (!navigator.storage?.estimate) return null
  try {
    return await navigator.storage.estimate()
  } catch {
    return null
  }
}
