import {
  getFullSongPcmChunk,
  readPcmChannel,
  type FullSongPcmChunkMeta,
} from './ai-storage'
import type { StemId } from './separation'

export interface PcmSlicePlan {
  index: number
  frames: number
}

/** The next overlapped window replaces the preceding window's tail. Plan a
 * single, contiguous PCM timeline before opening any multi-megabyte blobs. */
export function planContinuousPcmSlices(chunks: readonly FullSongPcmChunkMeta[]): {
  slices: PcmSlicePlan[]
  totalFrames: number
} {
  if (chunks.length === 0) throw new Error('沒有可合成的整首音軌暫存。')
  const ordered = [...chunks].sort((a, b) => a.index - b.index)
  const sampleRate = ordered[0]?.sampleRate
  const sourceImportedAt = ordered[0]?.sourceImportedAt
  if (sampleRate !== 44_100) throw new Error('整首音軌暫存採樣率不正確。')
  const slices: PcmSlicePlan[] = []
  let totalFrames = 0
  let logicalEnd = 0
  for (let i = 0; i < ordered.length; i += 1) {
    const current = ordered[i]
    const next = ordered[i + 1]
    if (!current || current.index !== i || current.sampleRate !== sampleRate || current.sourceImportedAt !== sourceImportedAt ||
      !Number.isInteger(current.startSample) || !Number.isInteger(current.sampleCount) ||
      current.sampleCount <= 0 || current.startSample !== totalFrames ||
      Math.abs(current.logicalStartTime - logicalEnd) > 0.02) {
      throw new Error('整首音軌暫存不連續；原有成品仍保留。')
    }
    if (next && (next.index !== i + 1 || next.sampleRate !== sampleRate ||
      Math.abs(next.logicalStartTime - (current.logicalStartTime + current.logicalDuration)) > 0.02 ||
      Math.abs(next.startSample - Math.round((next.logicalStartTime - 0.5) * sampleRate)) > 1)) {
      throw new Error('整首音軌暫存不連續；原有成品仍保留。')
    }
    const endSample = next ? next.startSample : current.startSample + current.sampleCount
    const frames = endSample - current.startSample
    if (frames <= 0 || frames > current.sampleCount) {
      throw new Error('整首音軌重疊長度不正確；原有成品仍保留。')
    }
    slices.push({ index: i, frames })
    totalFrames += frames
    logicalEnd = current.logicalStartTime + current.logicalDuration
  }
  if (Math.abs(totalFrames / sampleRate - logicalEnd) > 0.1) {
    throw new Error('整首音軌總長與來源不一致；原有成品仍保留。')
  }
  return { slices, totalFrames }
}

/** Reads only one stem of one window at a time. The AAC encoder consumes each
 * yielded slice before the next IndexedDB blob is decoded. */
export async function* streamStemPcmSlices(
  sourceImportedAt: string,
  id: StemId,
  plan: readonly PcmSlicePlan[],
  signal: AbortSignal,
): AsyncGenerator<{ left: Int16Array; right: Int16Array }> {
  for (const slice of plan) {
    if (signal.aborted) throw new DOMException('整首音軌壓縮已取消。', 'AbortError')
    const stored = await getFullSongPcmChunk(sourceImportedAt, slice.index)
    const stem = stored?.stems[id]
    if (!stored || !stem || stored.sampleCount < slice.frames || stored.sourceImportedAt !== sourceImportedAt) {
      throw new Error(`找不到第 ${slice.index + 1} 段的 ${id} 暫存音軌；原有成品仍保留。`)
    }
    const [left, right] = await Promise.all([readPcmChannel(stem.left), readPcmChannel(stem.right)])
    if (left.length !== stored.sampleCount || right.length !== stored.sampleCount) {
      throw new Error(`第 ${slice.index + 1} 段的 ${id} 暫存音軌已損壞；原有成品仍保留。`)
    }
    yield { left: left.subarray(0, slice.frames), right: right.subarray(0, slice.frames) }
  }
}
