import type { CompactSeparationResult, DecodedClip, SeparationProgress } from './separation'
import type {
  SeparationWorkerRequest,
  SeparationWorkerResponse,
} from '../workers/separation-worker'

export function separateClipsInWorker(
  model: Blob,
  clips: DecodedClip[],
  signal: AbortSignal,
  onProgress: (progress: SeparationProgress) => void,
): Promise<CompactSeparationResult[]> {
  if (signal.aborted) return Promise.reject(new DOMException('AI 分離已取消。', 'AbortError'))

  return new Promise((resolve, reject) => {
    const worker = new Worker(new URL('../workers/separation-worker.ts', import.meta.url), { type: 'module' })
    let settled = false
    const finish = (callback: () => void) => {
      if (settled) return
      settled = true
      signal.removeEventListener('abort', handleAbort)
      worker.terminate()
      callback()
    }
    const handleAbort = () => {
      finish(() => reject(new DOMException('AI 分離已取消。', 'AbortError')))
    }

    worker.onmessage = (event: MessageEvent<SeparationWorkerResponse>) => {
      const message = event.data
      if (message.type === 'progress') {
        onProgress(message)
        return
      }
      if (message.type === 'completed') {
        finish(() => resolve(message.results))
        return
      }
      finish(() => reject(new Error(message.message)))
    }
    worker.onerror = (event) => {
      finish(() => reject(new Error(event.message || 'AI 背景處理程序意外停止。')))
    }
    signal.addEventListener('abort', handleAbort, { once: true })
    const request: SeparationWorkerRequest = { type: 'start', model, clips }
    worker.postMessage(request, clips.flatMap((clip) => [clip.left.buffer, clip.right.buffer]))
  })
}
