import { AudioSample, AudioSampleSource, BufferTarget, Mp4OutputFormat, Output, Quality } from 'mediabunny'

export const stemM4aBitrate = 128_000
const encoderChunkFrames = 4_096

function pcm16WithGain(value: number, gain: number): number {
  return Math.max(-32_768, Math.min(32_767, Math.round(value * gain)))
}

/** Build one small interleaved frame block; never expand an entire stem to
 * Float32 or an AudioBuffer just to encode it. */
export function interleaveStereoPcm16(
  left: Int16Array,
  right: Int16Array,
  offset: number,
  frameCount: number,
  gain: number,
): Int16Array {
  const output = new Int16Array(frameCount * 2)
  for (let frame = 0; frame < frameCount; frame += 1) {
    output[frame * 2] = pcm16WithGain(left[offset + frame] ?? 0, gain)
    output[frame * 2 + 1] = pcm16WithGain(right[offset + frame] ?? 0, gain)
  }
  return output
}

/** Encode one stem to AAC in an M4A container on this device. Only a 4096-frame
 * PCM block and the much smaller compressed file are held during encoding. */
export async function encodeStereoM4a(
  left: Int16Array,
  right: Int16Array,
  gain: number,
  signal: AbortSignal,
  sampleRate = 44_100,
): Promise<Blob> {
  const frameCount = Math.min(left.length, right.length)
  if (frameCount <= 0) throw new Error('沒有可壓縮的音訊。')
  const target = new BufferTarget()
  const output = new Output({ format: new Mp4OutputFormat(), target })
  const audioSource = new AudioSampleSource({
    codec: 'aac',
    quality: new Quality({ bitrate: stemM4aBitrate }),
  })
  output.addAudioTrack(audioSource)
  let finalized = false
  try {
    await output.start()
    for (let offset = 0; offset < frameCount; offset += encoderChunkFrames) {
      if (signal.aborted) throw new DOMException('M4A 壓縮已取消。', 'AbortError')
      const length = Math.min(encoderChunkFrames, frameCount - offset)
      const sample = new AudioSample({
        data: interleaveStereoPcm16(left, right, offset, length, gain),
        format: 's16',
        numberOfChannels: 2,
        sampleRate,
        timestamp: offset / sampleRate,
      })
      try {
        await audioSource.add(sample)
      } finally {
        sample.close()
      }
    }
    if (signal.aborted) throw new DOMException('M4A 壓縮已取消。', 'AbortError')
    await output.finalize()
    finalized = true
    if (!target.buffer) throw new Error('M4A 壓縮沒有產生檔案。')
    return new Blob([target.buffer], { type: 'audio/mp4' })
  } finally {
    if (!finalized) await output.cancel().catch(() => undefined)
  }
}

export function estimateFourStemM4aBytes(seconds: number): number {
  return Math.ceil(Math.max(0, seconds) * stemM4aBitrate * 4 / 8)
}
