import {
  BlobSource,
  BufferTarget,
  EncodedAudioPacketSource,
  EncodedPacketSink,
  Input,
  Mp4InputFormat,
  Mp4OutputFormat,
  Output,
} from 'mediabunny'

/** Re-wrap two AAC streams without decoding the whole song. The old stream
 * is cut at joinTime; the next stream starts there and may contain PCM that
 * was crossfaded with an overlapping tail before encoding. */
export async function mergeM4aPackets(
  previous: Blob,
  next: Blob,
  joinTime: number,
  signal: AbortSignal,
  overlapSeconds = 0,
): Promise<Blob> {
  if (!Number.isFinite(joinTime) || joinTime <= 0) throw new Error('無效的音軌接合位置。')
  if (!Number.isFinite(overlapSeconds) || overlapSeconds < 0 || overlapSeconds > 1) throw new Error('無效的音軌重疊長度。')
  const target = new BufferTarget()
  const output = new Output({ format: new Mp4OutputFormat(), target })
  const source = new EncodedAudioPacketSource('aac')
  output.addAudioTrack(source)
  let finalized = false
  try {
    await output.start()
    let firstPacket = true
    for (const [blob, isPrevious] of [[previous, true], [next, false]] as const) {
      const input = new Input({ source: new BlobSource(blob, { maxCacheSize: 256 * 1024 }), formats: [new Mp4InputFormat()] })
      try {
        const track = await input.getPrimaryAudioTrack()
        if (!track) throw new Error('M4A 缺少音訊軌。')
        const config = await track.getDecoderConfig()
        if (!config || config.codec !== 'mp4a.40.2' || config.sampleRate !== 44_100 || config.numberOfChannels !== 2) {
          throw new Error('兩段音訊的 AAC 格式不同，不能直接合併。')
        }
        const sink = new EncodedPacketSink(track)
        let firstInputTimestamp: number | null = null
        let emitted = 0
        for await (const packet of sink.packets()) {
          if (signal.aborted) throw new DOMException('M4A 合併已取消。', 'AbortError')
          firstInputTimestamp ??= packet.timestamp
          // Safari's AAC encoder can emit 2–3 padding packets beyond the
          // captured PCM duration. They must not precede the next window's
          // first key packet in the output, or the MP4 muxer rejects it.
          if (isPrevious && packet.timestamp >= joinTime - 0.000001) {
            if (packet.timestamp > joinTime + overlapSeconds + 0.15) {
              throw new Error('AAC 片段尾端超出預期太多，無法安全合併；舊主檔已保留。')
            }
            continue
          }
          const timestamp = isPrevious
            ? packet.timestamp
            : joinTime + packet.timestamp - firstInputTimestamp
          await source.add(packet.clone({ timestamp }), firstPacket ? { decoderConfig: config } : undefined)
          firstPacket = false
          emitted += 1
        }
        if (emitted === 0) throw new Error('M4A 片段沒有可合併的音訊封包。')
      } finally {
        input.dispose()
      }
    }
    source.close()
    await output.finalize()
    finalized = true
    if (!target.buffer) throw new Error('M4A 合併沒有產生檔案。')
    return new Blob([target.buffer], { type: 'audio/mp4' })
  } finally {
    if (!finalized) await output.cancel().catch(() => undefined)
  }
}

/** Read MP4 headers without decoding the entire audio into RAM. */
export async function validateMergedM4a(blob: Blob, intendedDuration: number): Promise<void> {
  const input = new Input({ source: new BlobSource(blob, { maxCacheSize: 256 * 1024 }), formats: [new Mp4InputFormat()] })
  try {
    const track = await input.getPrimaryAudioTrack()
    if (!track) throw new Error('合併檔沒有音訊軌。')
    const config = await track.getDecoderConfig()
    if (config?.codec !== 'mp4a.40.2' || config.sampleRate !== 44_100 || config.numberOfChannels !== 2) {
      throw new Error('合併檔的 AAC 格式不正確。')
    }
    const actualDuration = await track.computeDuration()
    if (!Number.isFinite(actualDuration) || actualDuration < intendedDuration - 0.1 || actualDuration > intendedDuration + 0.1) {
      throw new Error(`合併檔長度不正確：${actualDuration.toFixed(3)} 秒。`)
    }
  } finally {
    input.dispose()
  }
}
