import { stemIds, type CompactSeparationResult, type StemId } from './separation'

export interface CachedAiModel {
  key: 'scnet-base-fp16-v1'
  size: number
  cachedAt: string
}

export interface StoredStemSet {
  key: 'current'
  sourceImportedAt: string
  sourceName: string
  startTime: number
  duration: number
  sampleRate: 44_100
  format: 'wav' | 'm4a'
  bass: Blob
  drums: Blob
  vocals: Blob
  other: Blob
  savedAt: string
}

export interface FullSongSegmentMeta {
  index: number
  sourceImportedAt: string
  startTime: number
  duration: number
  size: number
}

export interface StoredFullSongSegment extends Omit<StoredStemSet, 'key' | 'format'> {
  key: number
  format: 'm4a'
}

export interface FullSongWindowRecord {
  index: number
  startTime: number
  duration: number
}

export interface StoredFullSongMaster extends Omit<StoredStemSet, 'key' | 'format'> {
  key: 'current'
  format: 'm4a'
  windows: FullSongWindowRecord[]
  /** Final PCM from the last 0.5 seconds, used to blend the next AI window. */
  tail?: CompactSeparationResult
  joinQuality?: 'crossfade-0.5-v1' | 'continuous-aac-v2' | 'mixed'
}

/** A checkpoint contains one complete, unencoded AI window. Unlike the
 * logical window, its physical PCM may begin 0.5 s earlier for crossfading. */
export interface FullSongPcmChunkInput {
  sourceImportedAt: string
  sourceName: string
  index: number
  startTime: number
  duration: number
  logicalStartTime: number
  logicalDuration: number
  sampleRate: 44_100
  stems: CompactSeparationResult
  /** Small final PCM tail for resuming the next overlapping window. */
  tail?: CompactSeparationResult
}

export interface StoredPcmStereoStem {
  /** Raw, little-endian, signed PCM16 without a WAV header. */
  left: Blob
  right: Blob
}

export interface FullSongPcmChunkMeta {
  sourceImportedAt: string
  sourceName: string
  index: number
  startTime: number
  duration: number
  logicalStartTime: number
  logicalDuration: number
  sampleRate: 44_100
  startSample: number
  sampleCount: number
  size: number
  savedAt: string
}

export interface StoredFullSongPcmChunk extends FullSongPcmChunkMeta {
  stems: Record<StemId, StoredPcmStereoStem>
  tail?: CompactSeparationResult
}

const databaseName = 'transcribe-mobile-ai'
const databaseVersion = 6
const modelStore = 'models'
const stemStore = 'stem-results'
const fullSongStore = 'full-song-segments'
const fullSongMasterStore = 'full-song-master'
const fullSongPcmStore = 'full-song-pcm-chunks'

function openDatabase(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(databaseName, databaseVersion)
    request.onupgradeneeded = (event) => {
      const database = request.result
      if (!database.objectStoreNames.contains(modelStore)) {
        database.createObjectStore(modelStore, { keyPath: 'key' })
      }
      if (!database.objectStoreNames.contains(stemStore)) {
        database.createObjectStore(stemStore, { keyPath: 'key' })
      }
      if (!database.objectStoreNames.contains(fullSongStore)) {
        database.createObjectStore(fullSongStore, { keyPath: 'key' })
      }
      if (!database.objectStoreNames.contains(fullSongMasterStore)) {
        database.createObjectStore(fullSongMasterStore, { keyPath: 'key' })
      }
      if (!database.objectStoreNames.contains(fullSongPcmStore)) {
        database.createObjectStore(fullSongPcmStore, { keyPath: ['sourceImportedAt', 'index'] })
      }
      if (event.oldVersion < 3 && request.transaction && database.objectStoreNames.contains(modelStore)) {
        // Remove the older phone-incompatible HTDemucs metadata. SCNet uses
        // the same metadata key across its WebGPU and low-memory WASM modes.
        request.transaction.objectStore(modelStore).clear()
      }
    }
    request.onsuccess = () => resolve(request.result)
    request.onerror = () => reject(request.error ?? new Error('無法開啟本機 AI 儲存空間。'))
  })
}

function complete(transaction: IDBTransaction): Promise<void> {
  return new Promise((resolve, reject) => {
    transaction.oncomplete = () => resolve()
    transaction.onerror = () => reject(transaction.error ?? new Error('本機 AI 資料儲存失敗。'))
    transaction.onabort = () => reject(transaction.error ?? new Error('本機 AI 資料儲存已取消。'))
  })
}

async function getValue<T>(storeName: string, key: IDBValidKey): Promise<T | null> {
  const database = await openDatabase()
  try {
    return await new Promise((resolve, reject) => {
      const request = database.transaction(storeName, 'readonly').objectStore(storeName).get(key)
      request.onsuccess = () => resolve((request.result as T | undefined) ?? null)
      request.onerror = () => reject(request.error ?? new Error('無法讀取本機 AI 資料。'))
    })
  } finally {
    database.close()
  }
}

async function putValue<T>(storeName: string, value: T): Promise<void> {
  const database = await openDatabase()
  try {
    const transaction = database.transaction(storeName, 'readwrite')
    transaction.objectStore(storeName).put(value)
    await complete(transaction)
  } finally {
    database.close()
  }
}

async function deleteValue(storeName: string, key: IDBValidKey): Promise<void> {
  const database = await openDatabase()
  try {
    const transaction = database.transaction(storeName, 'readwrite')
    transaction.objectStore(storeName).delete(key)
    await complete(transaction)
  } finally {
    database.close()
  }
}

async function clearValues(storeName: string): Promise<void> {
  const database = await openDatabase()
  try {
    const transaction = database.transaction(storeName, 'readwrite')
    transaction.objectStore(storeName).clear()
    await complete(transaction)
  } finally {
    database.close()
  }
}

export function getCachedModel(): Promise<CachedAiModel | null> {
  return getValue<CachedAiModel>(modelStore, 'scnet-base-fp16-v1')
}

export async function saveCachedModel(size: number): Promise<CachedAiModel> {
  const model: CachedAiModel = {
    key: 'scnet-base-fp16-v1',
    size,
    cachedAt: new Date().toISOString(),
  }
  await putValue(modelStore, model)
  return model
}

export function deleteCachedModel(): Promise<void> {
  return deleteValue(modelStore, 'scnet-base-fp16-v1')
}

export function getStoredStemSet(): Promise<StoredStemSet | null> {
  return getValue<StoredStemSet>(stemStore, 'current')
}

export async function saveStoredStemSet(stems: Omit<StoredStemSet, 'key' | 'savedAt'>): Promise<StoredStemSet> {
  const stored: StoredStemSet = {
    ...stems,
    key: 'current',
    savedAt: new Date().toISOString(),
  }
  await putValue(stemStore, stored)
  return stored
}

export function deleteStoredStemSet(): Promise<void> {
  return deleteValue(stemStore, 'current')
}

export async function listFullSongSegments(sourceImportedAt: string): Promise<FullSongSegmentMeta[]> {
  const database = await openDatabase()
  try {
    const metadata = await new Promise<FullSongSegmentMeta[]>((resolve, reject) => {
      const segments: FullSongSegmentMeta[] = []
      const request = database.transaction(fullSongStore, 'readonly').objectStore(fullSongStore).openCursor()
      request.onsuccess = () => {
        const cursor = request.result
        if (!cursor) {
          resolve(segments)
          return
        }
        const segment = cursor.value as StoredFullSongSegment
        if (segment.sourceImportedAt === sourceImportedAt) {
          segments.push({
            index: segment.key,
            sourceImportedAt: segment.sourceImportedAt,
            startTime: segment.startTime,
            duration: segment.duration,
            size: segment.bass.size + segment.drums.size + segment.vocals.size + segment.other.size,
          })
        }
        cursor.continue()
      }
      request.onerror = () => reject(request.error ?? new Error('無法讀取整首分離進度。'))
    })
    return metadata.sort((first, second) => first.index - second.index)
  } finally {
    database.close()
  }
}

export function getFullSongSegment(index: number): Promise<StoredFullSongSegment | null> {
  return getValue<StoredFullSongSegment>(fullSongStore, index)
}

export async function saveFullSongSegment(
  index: number,
  stems: Omit<StoredStemSet, 'key' | 'savedAt' | 'format'> & { format: 'm4a' },
): Promise<FullSongSegmentMeta> {
  const stored: StoredFullSongSegment = {
    ...stems,
    key: index,
    savedAt: new Date().toISOString(),
  }
  await putValue(fullSongStore, stored)
  return {
    index,
    sourceImportedAt: stored.sourceImportedAt,
    startTime: stored.startTime,
    duration: stored.duration,
    size: stored.bass.size + stored.drums.size + stored.vocals.size + stored.other.size,
  }
}

export function deleteFullSongSegments(): Promise<void> {
  return clearValues(fullSongStore)
}

export function getFullSongMaster(): Promise<StoredFullSongMaster | null> {
  return getValue<StoredFullSongMaster>(fullSongMasterStore, 'current')
}

/** Replaces all four merged stems in one transaction. If migrating a legacy
 * window, that window is removed in the same commit, never beforehand. */
export async function saveFullSongMaster(
  master: Omit<StoredFullSongMaster, 'key' | 'savedAt'>,
  migratedSegmentIndex?: number,
): Promise<StoredFullSongMaster> {
  const stored: StoredFullSongMaster = {
    ...master,
    key: 'current',
    savedAt: new Date().toISOString(),
  }
  const database = await openDatabase()
  try {
    const stores = migratedSegmentIndex === undefined
      ? [fullSongMasterStore]
      : [fullSongMasterStore, fullSongStore]
    const transaction = database.transaction(stores, 'readwrite')
    transaction.objectStore(fullSongMasterStore).put(stored)
    if (migratedSegmentIndex !== undefined) transaction.objectStore(fullSongStore).delete(migratedSegmentIndex)
    await complete(transaction)
    return stored
  } finally {
    database.close()
  }
}

export async function deleteFullSongResults(): Promise<void> {
  const database = await openDatabase()
  try {
    const transaction = database.transaction([fullSongMasterStore, fullSongStore], 'readwrite')
    transaction.objectStore(fullSongMasterStore).delete('current')
    transaction.objectStore(fullSongStore).clear()
    await complete(transaction)
  } finally {
    database.close()
  }
}

function validatePcmChunk(chunk: FullSongPcmChunkInput): number {
  if (!chunk.sourceImportedAt || !chunk.sourceName || !Number.isSafeInteger(chunk.index) || chunk.index < 0) {
    throw new Error('無效的整首分離暫存識別。')
  }
  if (chunk.sampleRate !== 44_100 || !Number.isFinite(chunk.startTime) || chunk.startTime < 0 ||
    !Number.isFinite(chunk.duration) || chunk.duration <= 0 ||
    !Number.isFinite(chunk.logicalStartTime) || chunk.logicalStartTime < 0 ||
    !Number.isFinite(chunk.logicalDuration) || chunk.logicalDuration <= 0) {
    throw new Error('無效的整首分離暫存時間。')
  }
  if (chunk.logicalStartTime < chunk.startTime - 0.02 ||
    chunk.logicalStartTime + chunk.logicalDuration > chunk.startTime + chunk.duration + 0.02) {
    throw new Error('整首分離的實際音訊與進度時間不一致。')
  }
  const count = chunk.stems.bass.left.length
  if (count < 1 || Math.abs(count / chunk.sampleRate - chunk.duration) > 0.02 ||
    stemIds.some((id) => chunk.stems[id].left.length !== count || chunk.stems[id].right.length !== count)) {
    throw new Error('整首分離的四軌音訊長度不一致。')
  }
  if (chunk.tail) {
    const tailCount = chunk.tail.bass.left.length
    if (tailCount < 1 || tailCount > count ||
      stemIds.some((id) => chunk.tail![id].left.length !== tailCount || chunk.tail![id].right.length !== tailCount)) {
      throw new Error('整首分離的接合暫存長度不一致。')
    }
  }
  return count
}

function pcmChannelBlob(channel: Int16Array): Blob {
  // All model results are ordinary ArrayBuffers. A Blob remains file-backed in
  // IndexedDB, so reading one stem later need not materialize the other three.
  if (!(channel.buffer instanceof ArrayBuffer)) throw new Error('不支援共用記憶體音訊暫存。')
  const bytes = new Uint8Array(channel.buffer, channel.byteOffset, channel.byteLength)
  return new Blob([bytes], { type: 'application/octet-stream' })
}

function pcmMeta(chunk: StoredFullSongPcmChunk): FullSongPcmChunkMeta {
  return {
    sourceImportedAt: chunk.sourceImportedAt,
    sourceName: chunk.sourceName,
    index: chunk.index,
    startTime: chunk.startTime,
    duration: chunk.duration,
    logicalStartTime: chunk.logicalStartTime,
    logicalDuration: chunk.logicalDuration,
    sampleRate: chunk.sampleRate,
    startSample: chunk.startSample,
    sampleCount: chunk.sampleCount,
    size: chunk.size,
    savedAt: chunk.savedAt,
  }
}

/** Saves all four stems and the resume tail in one IndexedDB transaction. */
export async function saveFullSongPcmChunk(chunk: FullSongPcmChunkInput): Promise<FullSongPcmChunkMeta> {
  const sampleCount = validatePcmChunk(chunk)
  const stems = {} as Record<StemId, StoredPcmStereoStem>
  let size = 0
  for (const id of stemIds) {
    const left = pcmChannelBlob(chunk.stems[id].left)
    const right = pcmChannelBlob(chunk.stems[id].right)
    stems[id] = { left, right }
    size += left.size + right.size
  }
  const stored: StoredFullSongPcmChunk = {
    sourceImportedAt: chunk.sourceImportedAt,
    sourceName: chunk.sourceName,
    index: chunk.index,
    startTime: chunk.startTime,
    duration: chunk.duration,
    logicalStartTime: chunk.logicalStartTime,
    logicalDuration: chunk.logicalDuration,
    sampleRate: chunk.sampleRate,
    startSample: Math.round(chunk.startTime * chunk.sampleRate),
    sampleCount,
    size,
    savedAt: new Date().toISOString(),
    stems,
    ...(chunk.tail ? { tail: chunk.tail } : {}),
  }
  await putValue(fullSongPcmStore, stored)
  return pcmMeta(stored)
}

export function getFullSongPcmChunk(sourceImportedAt: string, index: number): Promise<StoredFullSongPcmChunk | null> {
  return getValue<StoredFullSongPcmChunk>(fullSongPcmStore, [sourceImportedAt, index])
}

/** Lists metadata only, in source order, without reading any PCM Blob bytes. */
export async function listFullSongPcmChunks(sourceImportedAt: string): Promise<FullSongPcmChunkMeta[]> {
  const database = await openDatabase()
  try {
    return await new Promise((resolve, reject) => {
      const chunks: FullSongPcmChunkMeta[] = []
      const range = IDBKeyRange.bound([sourceImportedAt, 0], [sourceImportedAt, Number.MAX_SAFE_INTEGER])
      const request = database.transaction(fullSongPcmStore, 'readonly').objectStore(fullSongPcmStore).openCursor(range)
      request.onsuccess = () => {
        const cursor = request.result
        if (!cursor) {
          resolve(chunks)
          return
        }
        chunks.push(pcmMeta(cursor.value as StoredFullSongPcmChunk))
        cursor.continue()
      }
      request.onerror = () => reject(request.error ?? new Error('無法讀取整首音訊暫存。'))
    })
  } finally {
    database.close()
  }
}

export function deleteFullSongPcmChunk(sourceImportedAt: string, index: number): Promise<void> {
  return deleteValue(fullSongPcmStore, [sourceImportedAt, index])
}

/** Deletes only this source's temporary PCM, never a saved M4A or model. */
export async function deleteFullSongPcmChunks(sourceImportedAt: string): Promise<void> {
  const database = await openDatabase()
  try {
    const transaction = database.transaction(fullSongPcmStore, 'readwrite')
    const done = complete(transaction)
    const range = IDBKeyRange.bound([sourceImportedAt, 0], [sourceImportedAt, Number.MAX_SAFE_INTEGER])
    const request = transaction.objectStore(fullSongPcmStore).openCursor(range)
    request.onsuccess = () => {
      const cursor = request.result
      if (!cursor) return
      cursor.delete()
      cursor.continue()
    }
    await done
  } finally {
    database.close()
  }
}

/** Loads just one PCM16 channel. The returned samples are still at the
 * compact model scale unless the caller applied final gain before saving. */
export async function readPcmChannel(blob: Blob): Promise<Int16Array> {
  const bytes = await blob.arrayBuffer()
  if (bytes.byteLength % Int16Array.BYTES_PER_ELEMENT !== 0) throw new Error('音訊暫存資料長度損壞。')
  return new Int16Array(bytes)
}
