import { stemIds, type StemId } from './separation'

/** Start a silent source and request resume in the same user gesture. */
export function activateAudioContext(context: AudioContext): Promise<void> {
  const silent = context.createBufferSource()
  silent.buffer = context.createBuffer(1, Math.max(1, Math.round(context.sampleRate * 0.05)), context.sampleRate)
  silent.connect(context.destination)
  silent.onended = () => silent.disconnect()
  silent.start()
  return context.resume()
}

/** Start the prepared audible stems before yielding to resume() or any other
 * promise. Safari may otherwise lose the user activation on the first tap. */
export function startPreparedStemSources(
  context: AudioContext,
  buffers: Record<StemId, AudioBuffer>,
  gains: Record<StemId, GainNode>,
  when: number,
  offset: number,
): { sources: AudioBufferSourceNode[]; activation: Promise<void> } {
  const activation = context.state === 'running' ? Promise.resolve() : activateAudioContext(context)
  const sources: AudioBufferSourceNode[] = []
  try {
    for (const id of stemIds) {
      const source = context.createBufferSource()
      source.buffer = buffers[id]
      source.connect(gains[id])
      sources.push(source)
    }
    for (const source of sources) source.start(when, offset)
    return { sources, activation }
  } catch (reason) {
    for (const source of sources) {
      try { source.stop() } catch { /* It may not have started. */ }
      source.disconnect()
    }
    void activation.catch(() => undefined)
    throw reason
  }
}
