import type { LocalAiCapabilities } from '../lib/ai-capabilities'
import { chooseSeparatorBackend } from '../lib/ai-capabilities'
import {
  deleteCachedModel,
  deleteFullSongPcmChunks,
  deleteFullSongResults,
  deleteStoredStemSet,
  getCachedModel,
  getFullSongMaster,
  getFullSongPcmChunk,
  getFullSongSegment,
  getStoredStemSet,
  listFullSongSegments,
  listFullSongPcmChunks,
  saveCachedModel,
  saveFullSongMaster,
  saveFullSongPcmChunk,
  saveStoredStemSet,
  type CachedAiModel,
  type FullSongSegmentMeta,
  type FullSongPcmChunkMeta,
  type StoredFullSongMaster,
  type StoredStemSet,
} from '../lib/ai-storage'
import { formatBytes, formatTime } from '../lib/audio'
import {
  approximateModelBytes,
  approximateRuntimeBytes,
  cacheAiRuntime,
  deleteCachedAiAssets,
  downloadSeparatorModel,
  getCachedSeparatorModel,
  hasCachedSeparatorModel,
  separationSampleRate,
  stemIds,
  type CompactSeparationResult,
} from '../lib/separation'
import {
  applyCompactGain,
  appendCompactSeparationSegment,
  copyCompactTail,
  createCompactSeparationAccumulator,
  crossfadeCompactHead,
  finishCompactSeparation,
} from '../lib/compact-separation'
import { separateClipsInWorker } from '../lib/separation-worker-client'
import { getStorageEstimate } from '../lib/storage'
import { encodeStereoPcm16Wav } from '../lib/wav'
import { encodeStereoM4a } from '../lib/m4a'
import { encodeContinuousStereoM4a } from '../lib/continuous-m4a'
import { mergeM4aPackets, validateMergedM4a } from '../lib/m4a-merge'
import { planContinuousPcmSlices, streamStemPcmSlices } from '../lib/full-song-pcm'
import { nextFullSongWindow, type FullSongWindow } from '../lib/full-song-plan'
import { createCapturePlan, sliceCapturedClip, type CapturedAudio } from '../lib/capture-plan'
import { StemMixer } from './StemMixer'
import { MergedStemMixer } from './MergedStemMixer'
import { createStemMixerSettings } from '../lib/stem-mixer'

type JobPhase = 'idle' | 'downloading' | 'decoding' | 'loading-model' | 'separating' | 'encoding' | 'merging' | 'ready'
type RecordedJobPhase = Exclude<JobPhase, 'idle' | 'ready'>

const interruptedJobKey = 'transcribe-pwa-interrupted-ai-job-v1'
const fullJoinSamples = Math.round(separationSampleRate * 0.5)
const fullJoinSeconds = fullJoinSamples / separationSampleRate

const phaseLabels: Record<RecordedJobPhase, string> = {
  downloading: '下載 AI 元件',
  decoding: '擷取音訊',
  'loading-model': '載入 AI 模型',
  separating: '執行分離',
  encoding: '壓縮四軌',
  merging: '合併整首音軌',
}

function recordJobPhase(phase: RecordedJobPhase): void {
  localStorage.setItem(interruptedJobKey, JSON.stringify({ phase, recordedAt: new Date().toISOString() }))
}

function clearRecordedJob(): void {
  localStorage.removeItem(interruptedJobKey)
}

function readInterruptedJob(): string | null {
  try {
    const value = JSON.parse(localStorage.getItem(interruptedJobKey) ?? '') as {
      phase?: RecordedJobPhase
      recordedAt?: string
    }
    clearRecordedJob()
    if (!value.phase || !(value.phase in phaseLabels)) return null
    return `上一次在「${phaseLabels[value.phase]}」時被中止。若畫面曾閃白或重新載入，通常是 iPhone 關閉了使用過多記憶體的頁面。`
  } catch {
    clearRecordedJob()
    return null
  }
}

interface StemResult {
  sourceImportedAt: string
  sourceName: string
  startTime: number
  duration: number
  format: 'wav' | 'm4a'
  bass: Blob
  drums: Blob
  vocals: Blob
  other: Blob
  tail?: CompactSeparationResult
  saved: boolean
}

interface Props {
  capabilities: LocalAiCapabilities | null
  checkingCapabilities: boolean
  currentTime: number
  sourceDuration: number
  sourceImportedAt: string
  sourceName: string
  onCheckCapabilities(): Promise<void>
  onBeforeSeparation(): void
  onBeforeStemPlayback(): void
  registerStemPause(pause: (() => void) | null): void
  captureClip(startTime: number, duration: number, signal: AbortSignal): Promise<CapturedAudio>
  onError(message: string): void
  onStorageChanged(): Promise<void>
}

function fromStored(stored: Omit<StoredStemSet, 'key' | 'savedAt'>): StemResult {
  return {
    sourceImportedAt: stored.sourceImportedAt,
    sourceName: stored.sourceName,
    startTime: stored.startTime,
    duration: stored.duration,
    format: stored.format ?? 'wav',
    bass: stored.bass,
    drums: stored.drums,
    vocals: stored.vocals,
    other: stored.other,
    saved: true,
  }
}

export function AiSeparationPanel({
  capabilities,
  checkingCapabilities,
  currentTime,
  sourceDuration,
  sourceImportedAt,
  sourceName,
  onCheckCapabilities,
  onBeforeSeparation,
  onBeforeStemPlayback,
  registerStemPause,
  captureClip,
  onError,
  onStorageChanged,
}: Props) {
  const downloadControllerRef = useRef<AbortController | null>(null)
  const jobControllerRef = useRef<AbortController | null>(null)
  const segmentSelectionRef = useRef(0)
  const fullPlaybackContextRef = useRef<AudioContext | null>(null)
  const fullMixerSettingsRef = useRef(createStemMixerSettings())
  const [model, setModel] = useState<CachedAiModel | null>(null)
  const [checkingCache, setCheckingCache] = useState(true)
  const [phase, setPhase] = useState<JobPhase>('idle')
  const [progress, setProgress] = useState(0)
  const [progressText, setProgressText] = useState('')
  const [experimentLength, setExperimentLength] = useState<15 | 30>(15)
  const [processingMode, setProcessingMode] = useState<'preview' | 'full'>('preview')
  const segmentLength = 8
  const overlapDuration = 0.5
  const [result, setResult] = useState<StemResult | null>(null)
  const [fullSegments, setFullSegments] = useState<FullSongSegmentMeta[]>([])
  const [fullPcmChunks, setFullPcmChunks] = useState<FullSongPcmChunkMeta[]>([])
  const [fullMaster, setFullMaster] = useState<StoredFullSongMaster | null>(null)
  const [selectedFullResult, setSelectedFullResult] = useState<StemResult | null>(null)
  const [selectedFullIndex, setSelectedFullIndex] = useState<number | null>(null)
  const [autoPlayFullIndex, setAutoPlayFullIndex] = useState<number | null>(null)
  const [resultMode, setResultMode] = useState<'preview' | 'full'>('preview')
  const [legacyResult, setLegacyResult] = useState(false)
  const [interruptedNotice, setInterruptedNotice] = useState(readInterruptedJob)

  const busy = phase === 'downloading' || phase === 'decoding' || phase === 'loading-model' || phase === 'separating' || phase === 'encoding' || phase === 'merging'
  const separatorBackend = capabilities ? chooseSeparatorBackend(capabilities) : 'unsupported'
  const wasmReady = separatorBackend === 'wasm-single'
  const lastLegacySegment = fullSegments.at(-1)
  const lastPcmChunk = fullPcmChunks.at(-1)
  const fullCompletedSeconds = Math.min(sourceDuration, lastPcmChunk
    ? lastPcmChunk.logicalStartTime + lastPcmChunk.logicalDuration
    : Math.max(fullMaster?.duration ?? 0, lastLegacySegment ? lastLegacySegment.startTime + lastLegacySegment.duration : 0))
  const fullSongComplete = sourceDuration > 0 &&
    fullMaster?.joinQuality === 'continuous-aac-v2' && fullMaster.duration >= sourceDuration - 0.05

  useEffect(() => {
    let active = true
    segmentSelectionRef.current += 1
    setCheckingCache(true)
    setFullSegments([])
    setFullPcmChunks([])
    setFullMaster(null)
    setSelectedFullResult(null)
    setSelectedFullIndex(null)
    setAutoPlayFullIndex(null)
    fullMixerSettingsRef.current = createStemMixerSettings()
    setResult(null)
    setResultMode('preview')
    setProcessingMode('preview')
    void Promise.all([getCachedModel(), hasCachedSeparatorModel(), getStoredStemSet(), listFullSongSegments(sourceImportedAt), getFullSongMaster(), listFullSongPcmChunks(sourceImportedAt)])
      .then(([cachedModel, modelFileExists, storedStems, storedSegments, storedMaster, storedPcmChunks]) => {
        if (!active) return
        setModel(modelFileExists ? cachedModel : null)
        setFullSegments(storedSegments)
        setFullPcmChunks(storedPcmChunks)
        if (storedMaster?.sourceImportedAt === sourceImportedAt) {
          setFullMaster(storedMaster)
          setResultMode('full')
        } else if (storedSegments.length > 0) {
          const last = storedSegments.at(-1)
          if (last) {
            const selection = ++segmentSelectionRef.current
            setResultMode('full')
            setSelectedFullIndex(last.index)
            void getFullSongSegment(last.index).then((segment) => {
              if (active && selection === segmentSelectionRef.current && segment?.sourceImportedAt === sourceImportedAt) setSelectedFullResult(fromStored(segment))
            }).catch((reason: unknown) => {
              if (active && selection === segmentSelectionRef.current) onError(reason instanceof Error ? reason.message : '無法讀取整首分離片段。')
            })
          }
        }
        if (storedPcmChunks.length > 0) setResultMode('full')
        if (cachedModel && !modelFileExists) void deleteCachedModel()
        if (storedStems?.sourceImportedAt === sourceImportedAt && storedStems.vocals instanceof Blob && storedStems.other instanceof Blob) {
          setResult(fromStored(storedStems))
          setLegacyResult(false)
          setPhase('ready')
        } else if (storedStems?.sourceImportedAt === sourceImportedAt) {
          setLegacyResult(true)
          setProgressText('找到舊版兩軌結果；請重新分離，就能取得四軌。')
        }
      })
      .catch((reason: unknown) => {
        if (active) onError(reason instanceof Error ? reason.message : '無法讀取本機 AI 資料。')
      })
      .finally(() => {
        if (active) setCheckingCache(false)
      })
    return () => {
      active = false
      downloadControllerRef.current?.abort()
      jobControllerRef.current?.abort()
      const playbackContext = fullPlaybackContextRef.current
      if (playbackContext && playbackContext.state !== 'closed') void playbackContext.close()
      fullPlaybackContextRef.current = null
    }
  }, [onError, sourceImportedAt])

  const downloadModel = async () => {
    if (!window.confirm('要下載約 35 MB 的低記憶體 AI 元件嗎？下載一次後會保存在這支手機，可供離線使用。')) return
    const estimate = await getStorageEstimate()
    if (estimate?.quota !== undefined && estimate.usage !== undefined) {
      const available = estimate.quota - estimate.usage
      if (available < approximateModelBytes + approximateRuntimeBytes + 64 * 1024 * 1024) {
        onError('手機提供給這個網站的可用空間不足。請先釋放至少 120 MB，再下載 AI 元件。')
        return
      }
    }

    const controller = new AbortController()
    downloadControllerRef.current = controller
    recordJobPhase('downloading')
    setPhase('downloading')
    setProgress(0)
    setProgressText('正在連線到模型下載來源…')
    try {
      const size = await downloadSeparatorModel(controller.signal, ({ loaded, total }) => {
        setProgress(Math.min(loaded / (total ?? approximateModelBytes), 1))
        setProgressText(`${formatBytes(loaded)} / ${total ? formatBytes(total) : '約 22 MB'}`)
      })
      const cached = await saveCachedModel(size)
      setProgressText('模型已保存；正在下載約 12 MB 的低記憶體 AI 執行引擎…')
      await cacheAiRuntime(controller.signal)
      setModel(cached)
      setPhase('idle')
      setProgress(0)
      setProgressText('模型已保存在這支手機。')
      clearRecordedJob()
      await onStorageChanged()
    } catch (reason) {
      await Promise.allSettled([deleteCachedModel(), deleteCachedAiAssets()])
      setModel(null)
      clearRecordedJob()
      setPhase('idle')
      if (reason instanceof DOMException && reason.name === 'AbortError') {
        setProgressText('下載已取消。')
      } else {
        onError(reason instanceof Error ? reason.message : 'AI 模型下載失敗。')
      }
    } finally {
      downloadControllerRef.current = null
    }
  }

  const removeModel = async () => {
    if (!window.confirm('要從這支手機刪除約 35 MB 的 AI 模型與執行引擎嗎？下次分離時需要重新下載。')) return
    await deleteCachedModel()
    await deleteCachedAiAssets()
    setModel(null)
    setProgressText('AI 模型已從手機刪除。')
    await onStorageChanged()
  }

  const appendToMaster = async (
    previous: StoredFullSongMaster | null,
    fresh: StemResult,
    signal: AbortSignal,
    migratedSegmentIndex?: number,
  ): Promise<StoredFullSongMaster> => {
    if (fresh.format !== 'm4a') throw new Error('整首音軌只接受 M4A 片段。')
    if (fresh.sourceImportedAt !== sourceImportedAt || (previous && previous.sourceImportedAt !== sourceImportedAt)) {
      throw new Error('音源已變更，不能合併舊音軌。')
    }
    const previousEnd = previous?.duration ?? 0
    const overlap = previousEnd - fresh.startTime
    if (overlap < -0.05 || overlap > fullJoinSeconds + 0.05 || (overlap > 0.05 && !previous?.tail)) {
      throw new Error('片段時間不連續，舊主檔已保留；請不要刪除原片段。')
    }
    const newDuration = fresh.startTime + fresh.duration
    if (newDuration <= previousEnd + 0.05) throw new Error('新片段沒有延長整首音軌；舊主檔已保留。')
    const merged = {} as Record<(typeof stemIds)[number], Blob>
    setPhase('merging')
    recordJobPhase('merging')
    for (const [index, id] of stemIds.entries()) {
      if (signal.aborted) throw new DOMException('合併已取消。', 'AbortError')
      setProgressText(`正在合併 ${id} · ${index + 1} / 4 軌；舊檔會保留到新檔驗證成功。`)
      merged[id] = previous
        ? await mergeM4aPackets(previous[id], fresh[id], fresh.startTime, signal, Math.max(0, overlap))
        : fresh[id]
      await validateMergedM4a(merged[id], newDuration)
      setProgress((index + 1) / stemIds.length)
    }
    if (signal.aborted) throw new DOMException('合併已取消。', 'AbortError')
    const stored = await saveFullSongMaster({
      sourceImportedAt,
      sourceName,
      startTime: 0,
      duration: newDuration,
      sampleRate: 44_100,
      format: 'm4a',
      windows: [
        ...(previous?.windows ?? []),
        { index: previous?.windows.length ?? 0, startTime: previousEnd, duration: newDuration - previousEnd },
      ],
      joinQuality: !previous && fresh.tail
        ? 'crossfade-0.5-v1'
        : previous?.joinQuality === 'crossfade-0.5-v1' && overlap > 0.05
          ? 'crossfade-0.5-v1'
          : 'mixed',
      ...(fresh.tail ? { tail: fresh.tail } : {}),
      ...merged,
    }, migratedSegmentIndex)
    setFullMaster(stored)
    if (migratedSegmentIndex !== undefined) {
      setFullSegments((current) => current.filter((segment) => segment.index !== migratedSegmentIndex))
    }
    await onStorageChanged()
    return stored
  }

  const migrateLegacySegments = async (
    startingMaster: StoredFullSongMaster | null,
    signal: AbortSignal,
  ): Promise<StoredFullSongMaster | null> => {
    let working = startingMaster
    for (const item of fullSegments) {
      if (signal.aborted) throw new DOMException('合併已取消。', 'AbortError')
      if (item.index < (working?.windows.length ?? 0)) continue
      if (item.index !== (working?.windows.length ?? 0)) throw new Error('舊片段不連續，請先保留資料並回報。')
      const stored = await getFullSongSegment(item.index)
      if (!stored || stored.sourceImportedAt !== sourceImportedAt) throw new Error(`找不到第 ${item.index + 1} 段舊片段。`)
      working = await appendToMaster(working, fromStored(stored), signal, item.index)
    }
    return working
  }

  /** Durable PCM checkpoints keep each AI job small. Only after every window
   * succeeds do we open one AAC encoder per stem and replace the old master. */
  const runFullContinuous = async () => {
    if (!model || !wasmReady || !capabilities?.aacEncoder || busy || jobControllerRef.current || fullSongComplete) return
    const controller = new AbortController()
    jobControllerRef.current = controller
    try {
      let chunks = await listFullSongPcmChunks(sourceImportedAt)
      if (chunks.length === 0) {
        const temporaryBytes = Math.ceil(sourceDuration * separationSampleRate * 2 * 2 * stemIds.length)
        const accepted = window.confirm(
          `新版整首模式會逐段保留原始四軌，最後一次壓成 M4A，避免每 15 秒的 AAC 接點靜音。` +
          `\n\n這首歌約需 ${formatBytes(temporaryBytes)} 手機暫存；成功後自動刪除。` +
          `\n舊版已完成的音軌會保留到新版四軌全部成功。要開始嗎？`,
        )
        if (!accepted) return
      }
      const savedBytes = chunks.reduce((sum, chunk) => sum + chunk.size, 0)
      const expectedBytes = Math.ceil(sourceDuration * separationSampleRate * 2 * 2 * stemIds.length)
      const estimate = await getStorageEstimate()
      if (estimate?.quota !== undefined && estimate.usage !== undefined &&
        estimate.quota - estimate.usage < Math.max(0, expectedBytes - savedBytes) + 64 * 1024 * 1024) {
        throw new Error(`手機提供給此網站的空間不足。整首模式還需約 ${formatBytes(Math.max(0, expectedBytes - savedBytes) + 64 * 1024 * 1024)}。`)
      }
      onBeforeSeparation()
      setResultMode('full')
      let nextWindow = nextFullSongWindow(
        chunks.map((chunk) => ({ index: chunk.index, startTime: chunk.logicalStartTime, duration: chunk.logicalDuration })),
        sourceDuration,
        15,
      )
      const modelBlob = nextWindow ? await getCachedSeparatorModel() : null
      if (nextWindow && !modelBlob) throw new Error('找不到已下載的 AI 模型，請先重新安裝 AI 元件。')

      while (nextWindow) {
        if (controller.signal.aborted) throw new DOMException('整首分離已取消。', 'AbortError')
        const currentWindow = nextWindow
        const previous = currentWindow.index > 0 ? await getFullSongPcmChunk(sourceImportedAt, currentWindow.index - 1) : null
        const joinSeconds = previous?.tail ? fullJoinSeconds : 0
        if (currentWindow.index > 0 && !previous?.tail) throw new Error('缺少上一段接合資料；舊版成品仍保留。')
        const physicalStart = currentWindow.startTime - joinSeconds
        const captureDuration = currentWindow.duration + joinSeconds
        setPhase('decoding')
        recordJobPhase('decoding')
        setProgress(0)
        setProgressText(`第 ${currentWindow.index + 1} 段：正在擷取 ${captureDuration.toFixed(1)} 秒；請保持畫面開啟…`)
        const recording = await captureClip(physicalStart, captureDuration, controller.signal)
        const shortfall = captureDuration - recording.duration
        const finalWindow = currentWindow.startTime + currentWindow.duration >= sourceDuration - 0.05
        if (shortfall > 0.02 && (!finalWindow || shortfall > 0.12)) {
          throw new Error('音訊擷取提早結束，尚未保存這一段；請重試。')
        }
        const capturePlan = createCapturePlan(0, recording.duration, recording.duration, segmentLength, overlapDuration)
        if (capturePlan.length === 0) throw new Error('音訊擷取時間不足，請重試。')
        // MP3/AAC duration metadata can run a few frames past the last decoded
        // sample. Pad only the *final* window rather than making resume loop on
        // a tiny unplayable remainder; never hide an early interior stop.
        const outputSamples = Math.round((finalWindow ? captureDuration : recording.duration) * separationSampleRate)
        const accumulated = createCompactSeparationAccumulator(outputSamples)
        for (let index = 0; index < capturePlan.length; index += 1) {
          const segment = capturePlan[index]
          if (!segment) continue
          if (controller.signal.aborted) throw new DOMException('整首分離已取消。', 'AbortError')
          const clip = sliceCapturedClip(recording, segment, separationSampleRate)
          setPhase('loading-model')
          recordJobPhase('loading-model')
          setProgressText(`第 ${currentWindow.index + 1} 段：正在為第 ${index + 1} / ${capturePlan.length} 個 AI 工作區載入模型…`)
          const separated = await separateClipsInWorker(modelBlob!, [clip], controller.signal, ({ progress: inferenceProgress }) => {
            setPhase('separating')
            recordJobPhase('separating')
            setProgress((index + Math.max(inferenceProgress, 0.15)) / capturePlan.length)
            setProgressText(`第 ${currentWindow.index + 1} 段：背景分離第 ${index + 1} / ${capturePlan.length} 個區塊；請不要切換其他 App…`)
          })
          const separatedSegment = separated[0]
          if (!separatedSegment) throw new Error(`第 ${currentWindow.index + 1} 段沒有產生分離結果。`)
          appendCompactSeparationSegment(
            accumulated,
            separatedSegment,
            Math.round(segment.startTime * separationSampleRate),
            Math.round(overlapDuration * separationSampleRate),
          )
          setProgress((index + 1) / capturePlan.length)
          if (index < capturePlan.length - 1) {
            setPhase('loading-model')
            setProgressText(`第 ${currentWindow.index + 1} 段：正在釋放 AI 記憶體…`)
            await new Promise((resolve) => window.setTimeout(resolve, 5_000))
          }
        }
        const outputGain = finishCompactSeparation(accumulated)
        applyCompactGain(accumulated, outputGain)
        if (joinSeconds > 0 && previous?.tail) crossfadeCompactHead(accumulated, previous.tail, fullJoinSamples)
        const tail = copyCompactTail(accumulated, fullJoinSamples)
        setPhase('merging')
        recordJobPhase('merging')
        setProgressText(`第 ${currentWindow.index + 1} 段：安全保存四軌原始音訊…`)
        const saved = await saveFullSongPcmChunk({
          sourceImportedAt,
          sourceName,
          index: currentWindow.index,
          startTime: physicalStart,
          duration: accumulated.bass.left.length / separationSampleRate,
          logicalStartTime: currentWindow.startTime,
          logicalDuration: currentWindow.duration,
          sampleRate: separationSampleRate,
          stems: accumulated,
          tail,
        })
        chunks = [...chunks, saved]
        setFullPcmChunks(chunks)
        await onStorageChanged()
        setProgressText(`已安全保存至 ${formatTime(currentWindow.startTime + currentWindow.duration, true)}；下一段可接著處理。`)
        nextWindow = nextFullSongWindow(
          chunks.map((chunk) => ({ index: chunk.index, startTime: chunk.logicalStartTime, duration: chunk.logicalDuration })),
          sourceDuration,
          15,
        )
        if (nextWindow) await new Promise((resolve) => window.setTimeout(resolve, 3_000))
      }

      const plan = planContinuousPcmSlices(chunks)
      const compressed = {} as Record<(typeof stemIds)[number], Blob>
      setPhase('encoding')
      recordJobPhase('encoding')
      for (const [index, id] of stemIds.entries()) {
        if (controller.signal.aborted) throw new DOMException('整首音軌壓縮已取消。', 'AbortError')
        setProgress(index / stemIds.length)
        setProgressText(`正在連續壓縮 ${id} · ${index + 1} / 4 軌；不會在 15 秒處重新啟動編碼器…`)
        compressed[id] = await encodeContinuousStereoM4a(
          streamStemPcmSlices(sourceImportedAt, id, plan.slices, controller.signal),
          controller.signal,
          { expectedFrames: plan.totalFrames },
        )
        await validateMergedM4a(compressed[id], plan.totalFrames / separationSampleRate)
      }
      const stored = await saveFullSongMaster({
        sourceImportedAt,
        sourceName,
        startTime: 0,
        duration: plan.totalFrames / separationSampleRate,
        sampleRate: separationSampleRate,
        format: 'm4a',
        windows: chunks.map((chunk) => ({ index: chunk.index, startTime: chunk.logicalStartTime, duration: chunk.logicalDuration })),
        joinQuality: 'continuous-aac-v2',
        ...compressed,
      })
      setFullMaster(stored)
      setProgress(1)
      setProgressText('整首四軌已用連續 AAC 壓縮完成；正在清理手機暫存…')
      clearRecordedJob()
      try {
        await deleteFullSongPcmChunks(sourceImportedAt)
        setFullPcmChunks([])
        await onStorageChanged()
        setProgressText('整首四軌已完成；接點不再由各段 AAC 編碼器產生。原始暫存已清除。')
      } catch {
        setProgressText('整首四軌已完成，但暫存清理失敗；可稍後使用「刪除暫存」釋放空間。')
      }
      setPhase('ready')
    } catch (reason) {
      clearRecordedJob()
      setPhase('idle')
      setProgress(0)
      if (reason instanceof DOMException && reason.name === 'AbortError') {
        setProgressText('已取消；已保存的原始音軌片段與舊版成品都還在手機，可稍後繼續。')
      } else {
        onError(reason instanceof Error ? reason.message : '整首連續壓縮失敗；舊版成品仍保留。')
      }
    } finally {
      jobControllerRef.current = null
    }
  }

  const runExperiment = async (mode: 'preview' | 'full' = 'preview') => {
    if (!model || !wasmReady || busy || jobControllerRef.current) return
    if (mode === 'full' && !capabilities?.aacEncoder) {
      onError('整首分離需要這支手機支援 AAC／M4A，避免四軌 WAV 佔滿儲存空間。')
      return
    }
    if (mode === 'preview' && Math.min(experimentLength, Math.max(0, sourceDuration - currentTime)) <= 0.05) {
      onError('目前位置已經在歌曲結尾，請把播放位置往前移。')
      return
    }
    const controller = new AbortController()
    jobControllerRef.current = controller
    onBeforeSeparation()
    if (mode === 'preview') setResult(null)
    setProgress(0)
    setPhase('loading-model')
    recordJobPhase('loading-model')
    setProgressText(mode === 'full' ? '正在準備整首歌曲並檢查已儲存的片段…' : '正在準備低記憶體 AI 模型…')
    try {
      let workingMaster = fullMaster
      if (mode === 'full' && fullSegments.length > 0) {
        workingMaster = await migrateLegacySegments(workingMaster, controller.signal)
      }
      let fullWindow: FullSongWindow | null = mode === 'full'
        ? nextFullSongWindow(workingMaster?.windows ?? [], sourceDuration, experimentLength)
        : null
      if (mode === 'full' && !fullWindow) {
        setPhase('ready')
        setProgressText('整首歌曲的四軌已全部合併。')
        clearRecordedJob()
        return
      }
      const modelBlob = await getCachedSeparatorModel()
      if (!modelBlob) throw new Error('找不到已下載的 AI 模型，請刪除 AI 元件後重新下載。')
      let previewSummary = ''
      do {
      const joinSeconds = fullWindow && workingMaster?.tail ? fullJoinSeconds : 0
      const startTime = (fullWindow?.startTime ?? currentTime) - joinSeconds
      const captureDuration = fullWindow
        ? fullWindow.duration + joinSeconds
        : Math.min(experimentLength, Math.max(0, sourceDuration - currentTime))
      setPhase('decoding')
      recordJobPhase('decoding')
      setProgressText(`${fullWindow ? `第 ${fullWindow.index + 1} 段：` : ''}正在擷取 ${captureDuration.toFixed(1)} 秒；請保持畫面開啟…`)
      const recording = await captureClip(startTime, captureDuration, controller.signal)
      const capturePlan = createCapturePlan(
        0,
        recording.duration,
        recording.duration,
        segmentLength,
        overlapDuration,
      )
      if (capturePlan.length === 0) throw new Error('音訊擷取時間不足，請重試。')
      const outputSamples = Math.round(recording.duration * separationSampleRate)
      const accumulated = createCompactSeparationAccumulator(outputSamples)
      for (let index = 0; index < capturePlan.length; index += 1) {
        const segment = capturePlan[index]
        if (!segment) continue
        if (controller.signal.aborted) throw new DOMException('AI 分離已取消。', 'AbortError')
        const clip = sliceCapturedClip(recording, segment, separationSampleRate)
        setProgress((index + 0.12) / capturePlan.length)
        setPhase('loading-model')
        recordJobPhase('loading-model')
        setProgressText(`正在為第 ${index + 1} / ${capturePlan.length} 段建立獨立 AI 工作區…`)
        {
          const separated = await separateClipsInWorker(modelBlob, [clip], controller.signal, ({
            progress: inferenceProgress,
          }) => {
            setPhase('separating')
            recordJobPhase('separating')
            setProgress((index + Math.max(inferenceProgress, 0.15)) / capturePlan.length)
            setProgressText(`正在背景分離第 ${index + 1} / ${capturePlan.length} 段；可按取消，但請不要切換其他 App…`)
          })
          const separatedSegment = separated[0]
          if (!separatedSegment) throw new Error(`第 ${index + 1} 段沒有產生分離結果。`)
          appendCompactSeparationSegment(
            accumulated,
            separatedSegment,
            Math.round(segment.startTime * separationSampleRate),
            Math.round(overlapDuration * separationSampleRate),
          )
        }
        setProgress((index + 1) / capturePlan.length)
        if (index < capturePlan.length - 1) {
          setPhase('loading-model')
          setProgressText(`第 ${index + 1} 段完成；正在釋放 AI 記憶體…`)
          await new Promise((resolve) => window.setTimeout(resolve, 5_000))
        }
      }
      const outputGain = finishCompactSeparation(accumulated)
      const resultDuration = accumulated.bass.left.length / separationSampleRate
      let encodeGain = outputGain
      let tail: CompactSeparationResult | undefined
      if (fullWindow) {
        applyCompactGain(accumulated, outputGain)
        if (joinSeconds > 0 && workingMaster?.tail) {
          crossfadeCompactHead(accumulated, workingMaster.tail, fullJoinSamples)
        }
        tail = copyCompactTail(accumulated, fullJoinSamples)
        encodeGain = 1
      }
      let encoded: Record<(typeof stemIds)[number], Blob> | null = null
      let outputFormat: 'wav' | 'm4a' = 'wav'
      if (capabilities?.aacEncoder) {
        setPhase('encoding')
        recordJobPhase('encoding')
        setProgress(0)
        try {
          const compressed = {} as Record<(typeof stemIds)[number], Blob>
          for (const [index, id] of stemIds.entries()) {
            setProgressText(`正在本機壓縮 ${id} · ${index + 1} / 4 軌…`)
            compressed[id] = await encodeStereoM4a(
              accumulated[id].left,
              accumulated[id].right,
              encodeGain,
              controller.signal,
            )
            setProgress((index + 1) / stemIds.length)
          }
          encoded = compressed
          outputFormat = 'm4a'
        } catch (reason) {
          if (reason instanceof DOMException && reason.name === 'AbortError') throw reason
          setProgressText('這支手機無法完成 M4A 壓縮，改用 WAV 保留結果。')
        }
      }
      if (!encoded) {
        if (mode === 'full') throw new Error('本段 M4A 壓縮未成功；已完成的整首片段仍保留在手機。')
        encoded = {
          bass: encodeStereoPcm16Wav(accumulated.bass.left, accumulated.bass.right, outputGain),
          drums: encodeStereoPcm16Wav(accumulated.drums.left, accumulated.drums.right, outputGain),
          vocals: encodeStereoPcm16Wav(accumulated.vocals.left, accumulated.vocals.right, outputGain),
          other: encodeStereoPcm16Wav(accumulated.other.left, accumulated.other.right, outputGain),
        }
      }
      const nextResult: StemResult = {
        sourceImportedAt,
        sourceName,
        startTime,
        duration: resultDuration,
        format: outputFormat,
        ...(tail ? { tail } : {}),
        ...encoded,
        saved: false,
      }
      if (fullWindow) {
        workingMaster = await appendToMaster(workingMaster, nextResult, controller.signal)
        setResultMode('full')
        setProgressText(`已合併至 ${formatTime(workingMaster.duration, true)}；正在準備下一段。`)
      } else {
        setResult(nextResult)
        setResultMode('preview')
        previewSummary = `${resultDuration.toFixed(1)} 秒連續分離完成，已製作 ${outputFormat.toUpperCase()} 四軌。結果目前只在記憶體中。`
      }
      if (!fullWindow) break
      fullWindow = nextFullSongWindow(workingMaster?.windows ?? [], sourceDuration, experimentLength)
      if (fullWindow) {
        await new Promise((resolve) => window.setTimeout(resolve, 3_000))
        if (controller.signal.aborted) throw new DOMException('整首分離已取消。', 'AbortError')
      }
      } while (fullWindow)
      setPhase('ready')
      setProgress(1)
      setProgressText(mode === 'full'
        ? '目前可處理的整首歌曲已合併完成；四軌各保留一個 M4A 主檔。'
        : previewSummary)
      clearRecordedJob()
    } catch (reason) {
      clearRecordedJob()
      setPhase('idle')
      setProgress(0)
      if (reason instanceof DOMException && reason.name === 'AbortError') {
        setProgressText(mode === 'full' ? '已取消；之前合併完成的四軌主檔仍保留在手機，可稍後繼續。' : '處理已取消，未完成的片段已清除。')
        return
      }
      const message = reason instanceof Error ? reason.message : '本機 AI 分離失敗。'
      const memoryHint = /memory|buffer|device lost|allocation|out of/i.test(message)
        ? ' 這支 iPhone 可能無法連續完成目前長度，請重新開啟程式後改用 15 秒，並回報停止階段。'
        : ''
      onError(`${message}${memoryHint}`)
    } finally {
      jobControllerRef.current = null
    }
  }

  const keepResult = async () => {
    if (!result) return
    try {
      await saveStoredStemSet({
        sourceImportedAt: result.sourceImportedAt,
        sourceName: result.sourceName,
        startTime: result.startTime,
        duration: result.duration,
        sampleRate: 44_100,
        format: result.format,
        bass: result.bass,
        drums: result.drums,
        vocals: result.vocals,
        other: result.other,
      })
      setResult({ ...result, saved: true })
      setProgressText('四軌結果已保留在這支手機。')
      await onStorageChanged()
    } catch (reason) {
      onError(reason instanceof Error ? reason.message : '無法保留分離結果。')
    }
  }

  const removeResult = async () => {
    await deleteStoredStemSet()
    setResult(null)
    setPhase('idle')
    setProgress(0)
    setProgressText('分離結果已刪除。')
    await onStorageChanged()
  }

  const removeLegacyResult = async () => {
    if (!window.confirm('要刪除舊版兩軌結果，釋放手機儲存空間嗎？')) return
    await deleteStoredStemSet()
    setLegacyResult(false)
    setProgressText('舊版兩軌結果已刪除。')
    await onStorageChanged()
  }

  const selectFullSegment = async (segment: FullSongSegmentMeta, continuePlayback = false) => {
    if (busy) return
    const selection = ++segmentSelectionRef.current
    setSelectedFullIndex(segment.index)
    setAutoPlayFullIndex(continuePlayback ? segment.index : null)
    setSelectedFullResult(null)
    setResultMode('full')
    try {
      const stored = await getFullSongSegment(segment.index)
      if (!stored || stored.sourceImportedAt !== sourceImportedAt) throw new Error('找不到這段四軌音訊，請重新開啟頁面。')
      if (selection === segmentSelectionRef.current) setSelectedFullResult(fromStored(stored))
    } catch (reason) {
      if (selection === segmentSelectionRef.current) onError(reason instanceof Error ? reason.message : '無法讀取整首分離片段。')
    }
  }

  const removeFullResults = async () => {
    if (!window.confirm('要刪除這首歌已完成的四軌主檔、舊片段和新版暫存嗎？刪除後必須從頭重新分離。')) return
    try {
      await deleteFullSongResults()
      await deleteFullSongPcmChunks(sourceImportedAt)
      segmentSelectionRef.current += 1
      setFullSegments([])
      setFullPcmChunks([])
      setFullMaster(null)
      setSelectedFullResult(null)
      setSelectedFullIndex(null)
      setAutoPlayFullIndex(null)
      const playbackContext = fullPlaybackContextRef.current
      if (playbackContext && playbackContext.state !== 'closed') void playbackContext.close()
      fullPlaybackContextRef.current = null
      setResultMode(result ? 'preview' : 'full')
      setProgressText('整首四軌主檔、舊片段與新版暫存已從手機刪除。')
      await onStorageChanged()
    } catch (reason) {
      onError(reason instanceof Error ? reason.message : '無法刪除整首分離片段。')
    }
  }

  const removeFinishedPcmCache = async () => {
    if (fullMaster?.joinQuality !== 'continuous-aac-v2') return
    try {
      await deleteFullSongPcmChunks(sourceImportedAt)
      setFullPcmChunks([])
      setProgressText('新版原始音軌暫存已清除；四軌 M4A 成品保留。')
      await onStorageChanged()
    } catch (reason) {
      onError(reason instanceof Error ? reason.message : '暫存清理失敗。')
    }
  }

  const exportMasterStem = (id: (typeof stemIds)[number]) => {
    if (!fullMaster) return
    const safeName = sourceName.replace(/\.[^.]+$/, '').replace(/[<>:"/\\|?*]/g, '_')
      .split('').map((character) => character.charCodeAt(0) < 32 ? '_' : character).join('').slice(0, 80)
    const url = URL.createObjectURL(fullMaster[id])
    const link = document.createElement('a')
    link.href = url
    link.download = `${safeName}-${id}.m4a`
    document.body.append(link)
    link.click()
    link.remove()
    window.setTimeout(() => URL.revokeObjectURL(url), 60_000)
  }

  if (checkingCache) {
    return <section className="panel ai-panel"><p>正在檢查手機內的 AI 模型…</p></section>
  }

  return (
    <section className="panel ai-panel">
      <div className="panel-heading"><span>本機 AI 分離實驗</span><b>音樂不會上傳</b></div>
      {interruptedNotice && (
        <div className="ai-interrupted" role="alert">
          <span>{interruptedNotice}</span>
          <button type="button" onClick={() => setInterruptedNotice(null)}>知道了</button>
        </div>
      )}
      {!capabilities ? (
        <>
          <p>先確認這支 iPhone 能否使用低記憶體 CPU／WASM；這一步不會下載約 35 MB 的手機版 AI 元件。</p>
          <button className="ai-check-button" type="button" disabled={checkingCapabilities} onClick={() => void onCheckCapabilities()}>
            {checkingCapabilities ? '正在檢查…' : '檢查這支手機'}
          </button>
        </>
      ) : (
        <div className="capability-results">
          <span>安全連線<strong>{capabilities.secureContext ? '可用' : '不可用'}</strong></span>
          <span>低記憶體模式<strong>{capabilities.webAssembly ? 'CPU／WASM' : '不支援'}</strong></span>
          <span>WebGPU<strong>{capabilities.webGpu ? '可用但停用' : '不可用'}</strong></span>
          <span>AAC／M4A 壓縮<strong>{capabilities.aacEncoder ? '可用' : '尚不可用'}</strong></span>
        </div>
      )}

      {capabilities && !wasmReady && (
        <p className="ai-warning">這支手機沒有可用的 WebAssembly，不能進行低記憶體本機 AI 分離。</p>
      )}

      {wasmReady && !model && (
        <div className="ai-step">
          <p>手機符合相容模式條件。這版不使用 WebGPU，改用較慢但較穩定的單執行緒 CPU／WASM。</p>
          <button className="ai-check-button" type="button" disabled={busy} onClick={() => void downloadModel()}>下載低記憶體 AI 元件（約 35 MB）</button>
        </div>
      )}

      {model && (
        <div className="ai-step">
          <div className="model-row">
            <span>SCNet Mobile<strong>已安裝 · 模型 {formatBytes(model.size)}</strong></span>
            <button type="button" disabled={busy} onClick={() => void removeModel()}>刪除模型</button>
          </div>
          <p>選擇短片段測試，或讓程式從頭逐段處理整首歌曲。整首模式每次前進 15 秒，暫存原始四軌，最後每軌只壓縮一次 M4A；成功後自動清除暫存。</p>
          <div className="clip-length-options three" role="group" aria-label="分離範圍">
            <button type="button" className={processingMode === 'preview' && experimentLength === 15 ? 'active' : ''} aria-pressed={processingMode === 'preview' && experimentLength === 15} disabled={busy} onClick={() => { setProcessingMode('preview'); setExperimentLength(15) }}>15 秒</button>
            <button type="button" className={processingMode === 'preview' && experimentLength === 30 ? 'active' : ''} aria-pressed={processingMode === 'preview' && experimentLength === 30} disabled={busy} onClick={() => { setProcessingMode('preview'); setExperimentLength(30) }}>30 秒</button>
            <button type="button" className={processingMode === 'full' ? 'active' : ''} aria-pressed={processingMode === 'full'} disabled={busy} onClick={() => { setProcessingMode('full'); setExperimentLength(15) }}>整首歌曲</button>
          </div>
          {processingMode === 'preview' && <div className="clip-controls"><span>測試長度最多 {experimentLength} 秒</span><span>起點 {formatTime(currentTime, true)}</span></div>}
          <button className="ai-check-button" type="button" disabled={busy || (processingMode === 'full' && (fullSongComplete || sourceDuration <= 0 || !capabilities?.aacEncoder))} onClick={() => processingMode === 'full' ? void runFullContinuous() : void runExperiment('preview')}>
            {busy && phase !== 'downloading' ? 'AI 正在處理…' : processingMode === 'preview' ? `分離目前位置後 ${experimentLength} 秒` : fullSongComplete ? '整首歌曲已完成' : fullPcmChunks.length ? '繼續新版整首分離／壓縮' : fullMaster ? '用無接點版重新分離整首（舊檔先保留）' : '開始分離整首歌曲'}
          </button>
          <div className="full-song-controls">
            <strong>整首歌曲 · 分段暫存、連續壓縮</strong>
            <p>每 15 秒安全保存一次原始四軌；整首完成後一次壓縮成四個 M4A。舊版成品會保留到新版成功，手機中途關閉也可從已保存位置繼續。處理時請保持畫面開啟。</p>
            {fullMaster && fullMaster.joinQuality !== 'continuous-aac-v2' && <small>目前播放器與下載仍是舊版有接點的音軌。新版成功前不會覆蓋它；新流程必須重新執行 AI 分離。</small>}
            <span>{fullPcmChunks.length ? '新版已暫存' : '已完成'} {formatTime(fullCompletedSeconds, true)} / {formatTime(sourceDuration, true)} · {fullPcmChunks.length || (fullMaster?.windows.length ?? 0) + fullSegments.length} 段 · {formatBytes(fullPcmChunks.length ? fullPcmChunks.reduce((sum, chunk) => sum + chunk.size, 0) : (fullMaster ? stemIds.reduce((sum, id) => sum + fullMaster[id].size, 0) : 0) + fullSegments.reduce((sum, segment) => sum + segment.size, 0))}</span>
            <progress max={Math.max(sourceDuration, 1)} value={fullCompletedSeconds} aria-label="整首分離進度" />
            {!capabilities?.aacEncoder && <small>此手機尚未提供 AAC／M4A 壓縮，整首分離暫不可用；上方短片段測試仍可使用 WAV。</small>}
            {fullPcmChunks.length > 0 && <small>新版原始四軌暫存會佔較多手機空間；成功輸出 M4A 後會自動刪除。若中斷，按上方按鈕可續做。</small>}
          </div>
        </div>
      )}

      {phase === 'downloading' && (
        <button className="ai-cancel-button" type="button" onClick={() => downloadControllerRef.current?.abort()}>取消下載</button>
      )}
      {busy && phase !== 'downloading' && (
        <button className="ai-cancel-button" type="button" onClick={() => jobControllerRef.current?.abort()}>取消處理</button>
      )}

      {(busy || progressText) && (
        <div className="ai-progress" aria-live="polite">
          {(phase === 'downloading' || phase === 'decoding' || phase === 'loading-model' || phase === 'separating' || phase === 'encoding' || phase === 'merging') && <progress max="1" value={progress} />}
          <span>{progressText}</span>
        </div>
      )}

      {legacyResult && !result && <button className="ai-cancel-button" type="button" disabled={busy} onClick={() => void removeLegacyResult()}>刪除舊版兩軌結果</button>}

      {result && (fullMaster || fullSegments.length > 0 || fullPcmChunks.length > 0) && (
        <div className="result-switch" role="group" aria-label="分離結果類型">
          <button type="button" className={resultMode === 'preview' ? 'active' : ''} disabled={busy} onClick={() => setResultMode('preview')}>短片段測試</button>
          <button type="button" className={resultMode === 'full' ? 'active' : ''} disabled={busy} onClick={() => setResultMode('full')}>整首進度</button>
        </div>
      )}

      {result && resultMode === 'preview' && (
        <div className="stem-results">
          <div className="stem-result-heading">
            <strong>分離結果</strong>
            <span>{formatTime(result.startTime, true)} 起 · {result.duration.toFixed(1)} 秒 · {result.format.toUpperCase()}</span>
          </div>
          <StemMixer
            key={`preview-${result.startTime}-${result.duration}`}
            stems={result}
            duration={result.duration}
            onBeforePlay={onBeforeStemPlayback}
            registerPause={registerStemPause}
            onError={onError}
          />
          <p>{result.saved ? '結果已保留在手機。' : '目前只是暫存；離開或重新整理後可能消失。'}</p>
          <div className="two-buttons">
            <button type="button" disabled={result.saved} onClick={() => void keepResult()}>{result.saved ? '已保留' : '保留到手機'}</button>
            <button className="danger-button" type="button" onClick={() => void removeResult()}>刪除結果</button>
          </div>
        </div>
      )}

      {fullMaster && resultMode === 'full' && (
        <div className="stem-results">
          <div className="stem-result-heading">
            <strong>已合併的四軌</strong>
            <span>{formatTime(fullMaster.duration, true)} · 四個 M4A 主檔</span>
          </div>
          {!busy && (
            <MergedStemMixer
              key={`${fullMaster.sourceImportedAt}-${fullMaster.windows.length}`}
              stems={fullMaster}
              duration={fullMaster.duration}
              onBeforePlay={onBeforeStemPlayback}
              registerPause={registerStemPause}
              onError={onError}
              settingsHolder={fullMixerSettingsRef}
            />
          )}
          {busy && <p>分離進行中；完成或取消後即可播放已合併的部分。</p>}
          <p>目前成品長度 {formatTime(fullMaster.duration, true)}。四軌各是一個檔案，可分別播放或靜音。{fullMaster.joinQuality !== 'continuous-aac-v2' && fullPcmChunks.length > 0 ? '新版正在製作，這裡暫時播放舊版成品。' : ''}</p>
          <div className="master-export-buttons" role="group" aria-label="下載合併音軌">
            {stemIds.map((id) => (
              <button key={id} type="button" disabled={busy} onClick={() => exportMasterStem(id)}>下載 {id.toUpperCase()} M4A</button>
            ))}
          </div>
          <button className="ai-cancel-button" type="button" disabled={busy} onClick={() => void removeFullResults()}>刪除整首分離進度與音軌</button>
          {fullMaster.joinQuality === 'continuous-aac-v2' && fullPcmChunks.length > 0 && <button type="button" disabled={busy} onClick={() => void removeFinishedPcmCache()}>只刪除新版原始音軌暫存</button>}
        </div>
      )}

      {!fullMaster && fullSegments.length > 0 && resultMode === 'full' && (
        <div className="stem-results">
          <div className="stem-result-heading">
            <strong>整首分離片段</strong>
            <span>{fullSongComplete ? '全部片段已保存' : '可從下一段續做'}</span>
          </div>
          <div className="full-segment-list" role="group" aria-label="選擇四軌片段">
            {fullSegments.map((segment) => (
              <button key={segment.index} type="button" disabled={busy} className={selectedFullIndex === segment.index ? 'active' : ''} aria-pressed={selectedFullIndex === segment.index} onClick={() => void selectFullSegment(segment)}>
                第 {segment.index + 1} 段<br />{formatTime(segment.startTime, true)}–{formatTime(segment.startTime + segment.duration, true)}
              </button>
            ))}
          </div>
          {selectedFullResult ? (
            <StemMixer
              key={`full-${selectedFullIndex}`}
              stems={selectedFullResult}
              duration={selectedFullResult.duration}
              onBeforePlay={onBeforeStemPlayback}
              registerPause={registerStemPause}
              onError={onError}
              contextHolder={fullPlaybackContextRef}
              settingsHolder={fullMixerSettingsRef}
              autoPlay={autoPlayFullIndex === selectedFullIndex}
              onEnded={() => {
                const next = fullSegments.find((segment) => segment.index === (selectedFullIndex ?? -1) + 1)
                if (next) void selectFullSegment(next, true)
              }}
            />
          ) : <p>正在讀取選取片段…</p>}
          <p>這些是舊版儲存的片段。選「整首歌曲」會先合併它們；合併成功後才刪除舊片段。現在仍可逐段播放。</p>
          <button className="ai-cancel-button" type="button" disabled={busy} onClick={() => void removeFullResults()}>刪除整首分離進度與音軌</button>
        </div>
      )}

      {!fullMaster && fullSegments.length === 0 && fullPcmChunks.length > 0 && resultMode === 'full' && (
        <div className="stem-results">
          <strong>新版整首分離暫存</strong>
          <p>已保存 {fullPcmChunks.length} 段原始四軌，尚未產生最終 M4A。按上方「繼續」可從下一段接著處理；完成後才會清除暫存。</p>
          <button className="ai-cancel-button" type="button" disabled={busy} onClick={() => void removeFullResults()}>刪除整首暫存</button>
        </div>
      )}

      <small className="experiment-note">整首模式會嘗試自動連續處理，每完成 15 秒就保存一次原始四軌；最後才壓縮成 M4A。若 Safari 關閉頁面，可重開後從已保存位置繼續；正在處理的那一段需要重做。請先用短歌曲驗證接點。</small>
    </section>
  )
}
