import { AudioSample, AudioSampleSource, BufferTarget, Mp4OutputFormat, Output, Quality } from 'mediabunny'
import { interleaveStereoPcm16, stemM4aBitrate } from './m4a'

const encoderChunkFrames = 4_096
const defaultSampleRate = 44_100

export interface StereoPcm16Chunk {
  left: Int16Array
  right: Int16Array
}

export interface StereoPcm16Block {
  data: Int16Array
  frameOffset: number
  frameCount: number
}

export interface ContinuousM4aOptions {
  /** The number of frames after trimming overlapping AI windows. */
  expectedFrames?: number
  gain?: number
}

function throwIfAborted(signal: AbortSignal): void {
  if (signal.aborted) throw new DOMException('M4A 壓縮已取消。', 'AbortError')
}

/** Reblock independently stored PCM windows into a single gapless sample
 * timeline. Only one source chunk plus at most one 4096-frame block is live. */
export async function* continuousStereoPcm16Blocks(
  chunks: AsyncIterable<StereoPcm16Chunk>,
  signal: AbortSignal,
  options: ContinuousM4aOptions = {},
): AsyncGenerator<StereoPcm16Block> {
  const gain = options.gain ?? 1
  if (!Number.isFinite(gain) || gain < 0) throw new Error('無效的音軌增益。')
  if (options.expectedFrames !== undefined && (!Number.isSafeInteger(options.expectedFrames) || options.expectedFrames <= 0)) {
    throw new Error('無效的預期音訊長度。')
  }

  let pending = new Int16Array(encoderChunkFrames * 2)
  let pendingFrames = 0
  let emittedFrames = 0
  let receivedFrames = 0

  for await (const { left, right } of chunks) {
    throwIfAborted(signal)
    if (left.length !== right.length) throw new Error('左右音軌的樣本數不同。')
    receivedFrames += left.length
    if (!Number.isSafeInteger(receivedFrames) || (options.expectedFrames !== undefined && receivedFrames > options.expectedFrames)) {
      throw new Error('音軌的樣本數超出預期。')
    }

    let offset = 0
    while (offset < left.length) {
      throwIfAborted(signal)
      if (pendingFrames === 0 && left.length - offset >= encoderChunkFrames) {
        yield {
          data: interleaveStereoPcm16(left, right, offset, encoderChunkFrames, gain),
          frameOffset: emittedFrames,
          frameCount: encoderChunkFrames,
        }
        emittedFrames += encoderChunkFrames
        offset += encoderChunkFrames
        continue
      }

      const take = Math.min(encoderChunkFrames - pendingFrames, left.length - offset)
      pending.set(interleaveStereoPcm16(left, right, offset, take, gain), pendingFrames * 2)
      pendingFrames += take
      offset += take
      if (pendingFrames === encoderChunkFrames) {
        yield { data: pending, frameOffset: emittedFrames, frameCount: encoderChunkFrames }
        emittedFrames += encoderChunkFrames
        pending = new Int16Array(encoderChunkFrames * 2)
        pendingFrames = 0
      }
    }
  }

  throwIfAborted(signal)
  if (options.expectedFrames !== undefined && receivedFrames !== options.expectedFrames) {
    throw new Error(`音軌樣本數不正確：預期 ${options.expectedFrames}，實際 ${receivedFrames}。`)
  }
  if (receivedFrames === 0) throw new Error('沒有可壓縮的音訊。')
  if (pendingFrames > 0) {
    yield {
      data: pending.subarray(0, pendingFrames * 2),
      frameOffset: emittedFrames,
      frameCount: pendingFrames,
    }
  }
}

/** Encode every PCM window with one AAC encoder and one MP4 output. AAC
 * priming therefore occurs only once, not once per 15-second AI window. */
export async function encodeContinuousStereoM4a(
  chunks: AsyncIterable<StereoPcm16Chunk>,
  signal: AbortSignal,
  options: ContinuousM4aOptions = {},
): Promise<Blob> {
  throwIfAborted(signal)
  const target = new BufferTarget()
  const output = new Output({ format: new Mp4OutputFormat(), target })
  const audioSource = new AudioSampleSource({
    codec: 'aac',
    quality: new Quality({ bitrate: stemM4aBitrate }),
  })
  output.addAudioTrack(audioSource)
  let finalized = false
  try {
    await output.start()
    for await (const block of continuousStereoPcm16Blocks(chunks, signal, options)) {
      throwIfAborted(signal)
      const sample = new AudioSample({
        data: block.data,
        format: 's16',
        numberOfChannels: 2,
        sampleRate: defaultSampleRate,
        timestamp: block.frameOffset / defaultSampleRate,
      })
      try {
        await audioSource.add(sample)
      } finally {
        sample.close()
      }
    }
    throwIfAborted(signal)
    await output.finalize()
    finalized = true
    if (!target.buffer) throw new Error('M4A 壓縮沒有產生檔案。')
    return new Blob([target.buffer], { type: 'audio/mp4' })
  } finally {
    if (!finalized) await output.cancel().catch(() => undefined)
  }
}
